class IncorrectRatStateDetected(Exception):
    """
    Raised when ratState is different than "ALL_ENABLED"
    """
    pass


class IncorrectProceduralStateDetected(Exception):
    """
    Raised when detected proceduralState is different than expected.
    """
    pass


class CellInfoForRmodNotFound(Exception):
    """
    Raised when cell info for RMOD could not be found.
    """
    pass


class DistnameForRmodNotFound(Exception):
    """
    Raised when dist_name for RMOD could not be found.
    """
    pass


class ParameterDoesNotExist(Exception):
    """
    Raised when parameter could not be found.
    """
    pass


class CellInfoNotFound(Exception):
    """
    Raised when cell info could not be found.
    """
    pass


class CellIdsNotFound(Exception):
    """
    Raised when cell ids could not be found
    """
    pass


class BbmodResetError(Exception):
    """
    Raised when bbmod reset finishes with status different than success.
    """
    pass


class GnssNotConfigured(Exception):
    """
    Raised when GNSS is not visible in the bts configuration.
    """
    pass


class RmodIdForCellIdNotFound(Exception):
    """
    Raised when RMOD index for cell ID could not be found.
    """
    pass


class ResponseFromApiChanged(Exception):
    """
    Raised when response structure from API has changed.
    """
    pass


class DifferentNumbersOfRmodsDetected(Exception):
    """
    Raised when number of Radio Modules determined from __init__.py is different from
    the one determined using admin API.
    """


class ObjectNotFound(Exception):
    """
    Raised when object could neither be found nor matched with other one
    """
    pass


class BtsNameNotFound(Exception):
    """
    Raised when BTS name cannot be found
    """
    pass


class TranslatedDistNameIsTheSame(Exception):
    """
    Raised when trying to translate distname to distname of the same type, e.g. runtime to runtime
    """
    pass


class CablinkForRmodPortNotFound(Exception):
    """
    Raised when cablink for given RMOD port could not be found
    """
    pass


class InvalidRATtype(Exception):
    """
    Raised when provided Rat type does not exist.
    """
    pass


class IncorrectX2LinkStateDetected(Exception):
    """
    Raised when X2 link state is different than expected.
    """
    pass


class RmodLinkProtocolNotFound(Exception):
    """
    Raised when RMOD link protocol cannot be found.
    """
    pass


class SyncStatusError(Exception):
    """
    Raised when sync status is different than expected.
    """
    pass


class MissingArgument(Exception):
    """
    Raised when a required argument is missing.
    """
    pass


class RmodSwVersionNotFound(Exception):
    """
    Raised when RMOD software version cannot be found.
    """
    pass


class MissingParametersError(Exception):
    """
    Raised when required parameters could not be found.
    """
    pass


class DistnameNotFoundError(Exception):
    """
    Raised when distname could not be found.
    """
    pass
